const UNCHANGED_V77={"assets/voice.js": "c95cfc5aa845c655435eb5458df035c8b52a8cf0ad038bccb54ee5980c5d77c4"};
function chapterHarness(){
 const e=app(),v=data();v.books.push({id:'b2',title:'Druga książka',child:'patryk',subject:'Polski'});
 v.bookPages=Array.from({length:80},(_,i)=>({id:'page'+String(i).padStart(4,'0'),bookId:'b1',number:i+1,imageId:'image'+i,text:i%2?'Tekst '+i:'',reviewed:i%3===0,chapter:'Dział 1'}));
 v.bookPages.push({id:'other',bookId:'b2',number:1,imageId:'other-image',text:'Inna książka',chapter:'Dział 1'});
 e.api.set(v,{adminTab:'book'});e.api.renderStub();seedBank(e);
 const boxes=v.bookPages.filter(p=>p.bookId==='b1').map(p=>({dataset:{pageSelect:p.id},checked:false}));
 const rows=boxes.map(box=>({dataset:{adminPageId:box.dataset.pageSelect},hidden:true,querySelector:()=>box}));
 const actions=[{disabled:true},{disabled:true}];
 e.document.querySelectorAll=sel=>sel==='[data-page-select]'?boxes:sel==='[data-page-select]:checked'?boxes.filter(x=>x.checked):sel==='[data-admin-page-id]'?rows:sel==='[data-chapter-needs-selection]'?actions:[];
 for(const [id,value] of Object.entries({'page-filter':'none','page-chapter-filter':'',chaptername:'',chapterfrom:'1',chapterto:'80'}))e.ids[id]={value};
 e.ids['page-selected-count']={};e.ids['chapter-selected-count']={};e.ids['page-filter-count']={};e.ids['v75-page-toolbar']={hidden:true};
 return {...e,v,boxes,rows,actions};
}
