function scopeHarness(numbers='1–16'){
 const e=chapterHarness();for(const p of e.v.bookPages){p.text='cat dog sun';p.reviewed=true;}
 e.ids['book-question-scope']={value:'selected'};e.ids['book-question-pages']={value:numbers};e.ids['book-question-pages-box']={hidden:false};e.ids['book-question-scope-count']={};e.ids['book-question-progress']=e.element();
 return e;
}
