function rangeHarness(){
 const e=scopeHarness();e.api.set(e.v,{role:'child',step:'pick'});for(let i=0;i<80;i++)e.v.bookPages[i].chapter=i<16?'Dział 1':'Dział 2';
 const control=(edge,value)=>({dataset:{v77RangeBook:'b1',v77RangeEdge:edge},value,hasAttribute:n=>n==='data-v77-range-book',matches:()=>false});
 const from=control('from','page0000'),to=control('to','page0079'),chapter={dataset:{v772ChapterBook:'b1'},value:'',hasAttribute:n=>n==='data-v772-chapter-book',matches:()=>false},summary={dataset:{v77RangeSummary:'b1'},textContent:''},error={dataset:{v772RangeError:'b1'},textContent:''},book={dataset:{tr71Book:'b1'},checked:false};
 e.ids['tr71-count']={};e.document.querySelectorAll=sel=>sel==='[data-v77-range-book]'?[from,to]:sel==='[data-v772-chapter-book]'?[chapter]:sel==='[data-v77-range-summary]'?[summary]:sel==='[data-v772-range-error]'?[error]:sel==='[data-tr71-book]'?[book]:[];
 return {...e,from,to,chapter,summary,error,book};
}
