function workerEnv(){const e=env();vm.runInContext(fs.readFileSync(ROOT+'/cloudflare-worker/worker.js','utf8').replace(/^import .*;\s*$/gm,'').replace(/^export \{.*\};\s*$/gm,'').replace('export default {','globalThis.worker={'),e.ctx);return e;}
await test('Worker ponawia niepełny JSON, lecz nie ponawia błędnego klucza ani limitu 429',async()=>{
 const e=workerEnv();let g=0,q=0,w=0;e.ctx.viaGemini=async()=>{g++;return g===1?'nie JSON':'{"issues":[]}';};e.ctx.viaGroq=async()=>{q++;throw Error('HTTP 429');};e.ctx.viaWorkersAI=async()=>{w++;throw Error('missing production AI binding');};const r=await e.ctx.reviewThree({}, {questions:[task()]});const b=await r.json();assert.equal(g,2);assert.equal(q,1);assert.equal(w,1);assert.equal(b.reviews[0].issues.length,0);assert.equal(b.reviews[1].code,'HTTP-429');
});
await test('Worker pyta tylko brakujących dostawców i wspólny tekst wysyła raz',async()=>{
 const e=workerEnv();let invoked=[];e.ctx.viaGemini=async()=>{throw Error('Nie wolno wywołać');};e.ctx.viaGroq=async(env,prompt,style,tokens,opts)=>{invoked.push({prompt,tokens,opts});return '{"issues":[]}';};e.ctx.viaWorkersAI=async()=>{throw Error('Nie wolno wywołać');};const r=await e.ctx.reviewThree({}, {providers:['groq'],questions:[{...task(),source:'SHARED_SOURCE_123'},{...task(),source:'SHARED_SOURCE_123'}]});assert.equal(r.status,200);assert.equal(invoked.length,1);assert.equal(invoked[0].tokens,3000);assert.equal((invoked[0].prompt.match(/SHARED_SOURCE_123/g)||[]).length,1);
});
